// Package brand carries the official PlainShow identity shared by every binary.
package brand

import (
	"encoding/base64"
	"net/http"
)

// IconWebP is the production PlainShow ribbon mark. Keeping it in the binary
// preserves the single-file and offline installation contract.
var IconWebP = func() []byte {
	data, err := base64.StdEncoding.DecodeString(iconWebPBase64)
	if err != nil {
		panic("plainshow brand icon: " + err.Error())
	}
	return data
}()

// ServeIcon writes the immutable production mark with long-lived cache headers.
func ServeIcon(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", "image/webp")
	w.Header().Set("Cache-Control", "public, max-age=31536000, immutable")
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write(IconWebP)
}

const iconWebPBase64 = ""
